# §15.4 exact totals enforced by validate_catalog().
EXPECTED_CATALOG_TOTALS = {
    "keys": 162,
    "domains": 20,
    "scope_NONE": 140,
    "scope_WAREHOUSE_REQUIRED": 10,
    "scope_OBJECT_REQUIRED": 2,
    "scope_UNRESOLVED": 10,
    "status_ENDPOINT": 11,
    "status_SERVICE": 53,
    "status_MATRIX": 88,
    "status_RESERVED": 10,
    "status_UNRESOLVED": 0,
    "sensitive": 29,
    "seed_GM": 152,
    "seed_ACCOUNTANT": 102,
    "seed_WAREHOUSE_KEEPER": 12,
}


class PermissionCatalogError(Exception):
    """Raised when the catalog registry violates an approved invariant."""


def validate_catalog() -> None:
    """Validate the registry against every §15/§15A/§15.4 invariant.

    Fails loudly (PermissionCatalogError) on any drift. Called by the
    seed migration data assertion (§15.1), the database system check,
    and the registry test suite. No Django/DB access; safe everywhere.
    """
    problems = []
    entries = SECURITY_PERMISSION_CATALOG
    keys = [entry["key"] for entry in entries]
    if len(entries) != EXPECTED_CATALOG_TOTALS["keys"]:
        problems.append(
            f"catalog has {len(entries)} entries, "
            f"expected {EXPECTED_CATALOG_TOTALS['keys']}"
        )
    seen = set()
    for entry in entries:
        key = entry["key"]
        if key in seen:
            problems.append(f"duplicate key {key!r}")
        seen.add(key)
        if not PERMISSION_KEY_PATTERN.match(key):
            problems.append(f"key {key!r} fails PERMISSION_KEY_REGEX")
        parts = key.split(".")
        if (
            len(parts) != 3
            or parts[0] != entry["domain"]
            or parts[1] != entry["resource"]
            or parts[2] != entry["action"]
        ):
            problems.append(f"key {key!r} does not decompose to its metadata")
        if entry["domain"] not in PERMISSION_DOMAINS:
            problems.append(f"unknown domain {entry['domain']!r} on {key!r}")
        if entry["scope_policy"] not in SCOPE_POLICIES:
            problems.append(f"unknown scope_policy {entry['scope_policy']!r} on {key!r}")
        if entry["status"] not in CATALOG_STATUSES:
            problems.append(f"unknown status {entry['status']!r} on {key!r}")
        if not entry["description"]:
            problems.append(f"missing description on {key!r}")
        if not isinstance(entry["is_sensitive"], bool):
            problems.append(f"non-bool is_sensitive on {key!r}")
    domains = {entry["domain"] for entry in entries}
    if len(domains) != EXPECTED_CATALOG_TOTALS["domains"]:
        problems.append(
            f"{len(domains)} distinct domains, expected "
            f"{EXPECTED_CATALOG_TOTALS['domains']}"
        )
    for policy in SCOPE_POLICIES:
        count = sum(1 for e in entries if e["scope_policy"] == policy)
        expected = EXPECTED_CATALOG_TOTALS[f"scope_{policy}"]
        if count != expected:
            problems.append(f"scope {policy}: {count} keys, expected {expected}")
    for status in CATALOG_STATUSES:
        count = sum(1 for e in entries if e["status"] == status)
        expected = EXPECTED_CATALOG_TOTALS[f"status_{status}"]
        if count != expected:
            problems.append(f"status {status}: {count} keys, expected {expected}")
    sensitive = sum(1 for e in entries if e["is_sensitive"])
    if sensitive != EXPECTED_CATALOG_TOTALS["sensitive"]:
        problems.append(f"{sensitive} sensitive keys, expected "
                        f"{EXPECTED_CATALOG_TOTALS['sensitive']}")
    if not UNRESOLVED_PERMISSION_KEYS:
        problems.append("UNRESOLVED key set must not be emptied silently")
    for key in UNRESOLVED_PERMISSION_KEYS:
        if key not in CATALOG_BY_KEY:
            problems.append(f"unresolved key {key!r} missing from catalog")
        elif CATALOG_BY_KEY[key]["scope_policy"] != "UNRESOLVED":
            problems.append(f"unresolved key {key!r} misclassified in catalog")
    seeds = {
        "GM": GM_SEED_PERMISSION_KEYS,
        "ACCOUNTANT": ACCOUNTANT_SEED_PERMISSION_KEYS,
        "WAREHOUSE_KEEPER": WAREHOUSE_KEEPER_SEED_PERMISSION_KEYS,
    }
    for role_code, seed_keys in seeds.items():
        expected_count = EXPECTED_CATALOG_TOTALS[f"seed_{role_code}"]
        if len(seed_keys) != expected_count:
            problems.append(
                f"{role_code} seed has {len(seed_keys)} keys, "
                f"expected {expected_count}"
            )
        for key in seed_keys:
            if key not in CATALOG_BY_KEY:
                problems.append(f"{role_code} seed key {key!r} not in catalog")
        overlap = sorted(set(seed_keys) & UNRESOLVED_PERMISSION_KEYS)
        if overlap:
            problems.append(f"{role_code} seed contains UNRESOLVED keys: {overlap}")
    if problems:
        raise PermissionCatalogError(
            "W0-2A permission catalog validation failed:\n  - "
            + "\n  - ".join(problems)
        )

